// Computes the maximum among the first `n` elements of `a`.
// Preconditions (as stated in the problem):
// - n > 0
// - n <= a.len()
// - n < 1000 (not required for correctness here, but assumed true)
fn max(a: &Vec<i32>, n: usize) -> i32 {
    assert!(n > 0, "n must be > 0");
    assert!(n <= a.len(), "n must be <= a.len()");

    let mut m = a[0];
    for i in 1..n {
        if a[i] > m {
            m = a[i];
        }
    }
    m
}

fn main() {
    // Example usage
    let a = vec![3, -1, 7, 2, 7, 0];
    let n = 4;
    let ans = max(&a, n);
    println!("{ans}"); // prints 7 (max of [3, -1, 7, 2])
}